def test_user_pagination_matches_naive_slicing(client):
    for i in range(5):
        client.post("/users", json={"username": f"user{i}", "email": f"user{i}@example.com"})

    page1 = client.get("/users", params={"skip": 0, "limit": 3}).json()
    page2 = client.get("/users", params={"skip": 3, "limit": 3}).json()

    assert [u["username"] for u in page1] == ["user0", "user1", "user2"], page1
    assert [u["username"] for u in page2] == ["user3", "user4"], page2


def test_project_pagination_matches_naive_slicing(client):
    user = client.post("/users", json={"username": "owner", "email": "owner@example.com"}).json()
    for i in range(4):
        client.post("/projects", json={"name": f"proj{i}", "owner_id": user["id"]})

    page = client.get("/projects", params={"skip": 1, "limit": 2}).json()
    assert [p["name"] for p in page] == ["proj1", "proj2"], page


def test_task_pagination_matches_naive_slicing(client):
    user = client.post("/users", json={"username": "dev", "email": "dev@example.com"}).json()
    project = client.post("/projects", json={"name": "P", "owner_id": user["id"]}).json()
    for i in range(6):
        client.post("/tasks", json={"title": f"task{i}", "project_id": project["id"]})

    page = client.get(
        "/tasks", params={"project_id": project["id"], "skip": 2, "limit": 3}
    ).json()
    assert [t["title"] for t in page] == ["task2", "task3", "task4"], page


